def process_deposits_C1() -> None:
    """Process deposits."""
    print("PROCESSING DEPOSITS...")
    global WS_FLAGS
    WS_FLAGS = WsFlagsC1(ws_eof_flag='N', ws_error_flag=WS_FLAGS.ws_error_flag, ws_valid_flag=WS_FLAGS.ws_valid_flag, ws_found_flag=WS_FLAGS.ws_found_flag, ws_approved_flag=WS_FLAGS.ws_approved_flag)
    while WS_FLAGS.ws_eof_flag == 'N':
        validate_deposit_C1()
        if WS_FLAGS.ws_valid_flag == 'Y':
            post_deposit_C1()
            update_balance_C1()
            global WS_COUNTERS
            WS_COUNTERS = WsCountersC1(ws_cust_count=WS_COUNTERS.ws_cust_count, ws_acct_count=WS_COUNTERS.ws_acct_count, ws_tran_count=WS_COUNTERS.ws_tran_count + 1, ws_loan_count=WS_COUNTERS.ws_loan_count, ws_ins_count=WS_COUNTERS.ws_ins_count, ws_inv_count=WS_COUNTERS.ws_inv_count, ws_error_count=WS_COUNTERS.ws_error_count, ws_process_count=WS_COUNTERS.ws_process_count)
        WS_FLAGS = WsFlagsC1(ws_eof_flag='Y', ws_error_flag=WS_FLAGS.ws_error_flag, ws_valid_flag=WS_FLAGS.ws_valid_flag, ws_found_flag=WS_FLAGS.ws_found_flag, ws_approved_flag=WS_FLAGS.ws_approved_flag)

def validate_deposit_C1() -> None:
    """Validate deposit."""
    global WS_FLAGS, WS_CALCULATION_FIELDS, ACCOUNT_RECORD
    WS_FLAGS = WsFlagsC1(ws_eof_flag=WS_FLAGS.ws_eof_flag, ws_error_flag=WS_FLAGS.ws_error_flag, ws_valid_flag='Y', ws_found_flag=WS_FLAGS.ws_found_flag, ws_approved_flag=WS_FLAGS.ws_approved_flag)
    if WS_CALCULATION_FIELDS.ws_calc_amount < 0:
        WS_FLAGS = WsFlagsC1(ws_eof_flag=WS_FLAGS.ws_eof_flag, ws_error_flag=WS_FLAGS.ws_error_flag, ws_valid_flag='N', ws_found_flag=WS_FLAGS.ws_found_flag, ws_approved_flag=WS_FLAGS.ws_approved_flag)
    if ACCOUNT_RECORD.acct_status != 'A':
        WS_FLAGS = WsFlagsC1(ws_eof_flag=WS_FLAGS.ws_eof_flag, ws_error_flag=WS_FLAGS.ws_error_flag, ws_valid_flag='N', ws_found_flag=WS_FLAGS.ws_found_flag, ws_approved_flag=WS_FLAGS.ws_approved_flag)

def post_deposit_C1() -> None:
    """Post deposit."""
    global WS_CALCULATION_FIELDS, ACCOUNT_RECORD, WS_TOTALS
    ACCOUNT_RECORD = AccountRecordC1(acct_id=ACCOUNT_RECORD.acct_id, acct_cust_id=ACCOUNT_RECORD.acct_cust_id, acct_type=ACCOUNT_RECORD.acct_type, acct_balance=ACCOUNT_RECORD.acct_balance + WS_CALCULATION_FIELDS.ws_calc_amount, acct_available=ACCOUNT_RECORD.acct_available + WS_CALCULATION_FIELDS.ws_calc_amount, acct_pending=ACCOUNT_RECORD.acct_pending, acct_interest_rate=ACCOUNT_RECORD.acct_interest_rate, acct_open_date=ACCOUNT_RECORD.acct_open_date, acct_last_trans_date=ACCOUNT_RECORD.acct_last_trans_date, acct_status=ACCOUNT_RECORD.acct_status, acct_overdraft_limit=ACCOUNT_RECORD.acct_overdraft_limit, acct_monthly_fee=ACCOUNT_RECORD.acct_monthly_fee, acct_min_balance=ACCOUNT_RECORD.acct_min_balance)
