    """Monitoring transactions."""
    global ws_not_eof, ws_eof, transaction_log
    print("MONITORING TRANSACTIONS...")
    ws_not_eof = True
    while not ws_eof:
        # Assuming transaction_log is a list of transactions
        try:
            transaction = next(iter(transaction_log), None)  # Get the next transaction
            if transaction is None:
                ws_eof = True
            else:
                c110_rule_based_detection_C4()
                c120_behavior_analysis_C4()
                c130_network_analysis_C4()
        except StopIteration:
            ws_eof = True
        break

