def d110_classification_C4() -> None:
    """Classification."""
    if (data_record_C4.cust_credit_score is not None and
            data_record_C4.cust_credit_score > 750):
        data_record_C4.cust_risk_rating = 'A'
    elif (data_record_C4.cust_credit_score is not None and
          data_record_C4.cust_credit_score > 650):
        data_record_C4.cust_risk_rating = 'B'
    elif (data_record_C4.cust_credit_score is not None and
          data_record_C4.cust_credit_score > 550):
        data_record_C4.cust_risk_rating = 'C'
    else:
        data_record_C4.cust_risk_rating = 'D'

