    if data_record_C4.cust_credit_score is not None and data_record_C4.cust_total_balance is not None and data_record_C4.cust_total_loans is not None:
        ws_calc_result = (data_record_C4.cust_credit_score * 10) + (data_record_C4.cust_total_balance / 1000) - (data_record_C4.cust_total_loans / 2000)
