def portfolio_management_C7():
    """Manages the investment portfolio."""
    load_portfolio_C7()
    update_market_prices_C7()
    calculate_values_C7()
    rebalance_check_C7()
    generate_statements_C7()

def load_portfolio_C7():
    """Loads the investment portfolio."""
    ws_hold_idx: int = 1
    ws_eof_flag: str = 'N'
    ws_holding: List[Any] = []
    ws_holdings_count: int = 0
    while not (ws_hold_idx > 100 or ws_eof_flag == 'Y'):
        holding_rec = read_holdings_file_C7()
        if holding_rec is None:
            ws_eof_flag = 'Y'
        else:
            ws_holding.append(holding_rec)
            ws_hold_idx += 1
    ws_holdings_count = ws_hold_idx - 1
    return ws_holding, ws_holdings_count

def update_market_prices_C7():
    """Updates market prices."""
    ws_holdings_count: int = 1
    for ws_hold_idx in range(1, ws_holdings_count + 1):
        ws_quote_symbol: str = get_hold_symbol_C7(ws_hold_idx)
        ws_quote_price: Decimal = get_quote_C7(ws_quote_symbol)
        set_hold_current_price_C7(ws_hold_idx, ws_quote_price)

def get_quote_C7(ws_quote_symbol: str) -> Decimal:
    """Gets a quote."""
    quote_request_symbol: str = ws_quote_symbol
    quote_response_status, quote_last_price = call_getquote_C7(quote_request_symbol)
    if quote_response_status == 'OK':
        ws_quote_price: Decimal = quote_last_price
    else:
        ws_quote_price: Decimal = Decimal("0.0")
    return ws_quote_price

def calculate_values_C7():
    """Calculates portfolio values."""
    ws_holdings_count: int = 1
    ws_total_value: Decimal = Decimal("0.0")
    ws_cost_basis: Decimal = Decimal("0.0")
    ws_unrealized_gain: Decimal = Decimal("0.0")
    for ws_hold_idx in range(1, ws_holdings_count + 1):
        ws_total_value, ws_cost_basis, ws_unrealized_gain = calculate_holding_value_C7(ws_hold_idx, ws_total_value, ws_cost_basis, ws_unrealized_gain)
    return ws_total_value, ws_cost_basis, ws_unrealized_gain

def calculate_holding_value_C7(ws_hold_idx: int, ws_total_value: Decimal, ws_cost_basis: Decimal, ws_unrealized_gain: Decimal) -> tuple[Decimal, Decimal, Decimal]:
    """Calculates the value of a holding."""
    hold_shares: int = 1
    hold_current_price: Decimal = Decimal("0.0")
    hold_cost_per_share: Decimal = Decimal("0.0")

    hold_market_value: Decimal = hold_shares * hold_current_price
    ws_hold_cost: Decimal = hold_shares * hold_cost_per_share
    hold_gain_loss: Decimal = hold_market_value - ws_hold_cost
    if ws_hold_cost > 0:
        hold_pct_change: Decimal = (hold_gain_loss / ws_hold_cost) * 100
    else:
        hold_pct_change: Decimal = Decimal("0.0")
    ws_total_value += hold_market_value
    ws_cost_basis += ws_hold_cost
    ws_unrealized_gain += hold_gain_loss
    return ws_total_value, ws_cost_basis, ws_unrealized_gain

def rebalance_check_C7():
    """Checks if rebalancing is needed."""
    ws_total_value: Decimal = Decimal("0.0")
    ws_rebalance_needed, ws_stocks_diff, ws_bonds_diff = calculate_current_allocation_C7(ws_total_value)
    ws_target_stocks_pct: Decimal = Decimal("0.0")
    ws_target_bonds_pct: Decimal = Decimal("0.0")

    ws_rebalance_needed = compare_to_target_C7(ws_target_stocks_pct, ws_target_bonds_pct, ws_stocks_diff, ws_bonds_diff)
    if ws_rebalance_needed == 'Y':
        generate_rebalance_trades_C7(ws_total_value, ws_stocks_diff)

def calculate_current_allocation_C7(ws_total_value: Decimal) -> tuple[str, Decimal, Decimal]:
    """Calculates the current asset allocation."""
    ws_holdings_count: int = 1
    ws_stocks_value: Decimal = Decimal("0.0")
    ws_bonds_value: Decimal = Decimal("0.0")
    ws_cash_value: Decimal = Decimal("0.0")
    for ws_hold_idx in range(1, ws_holdings_count + 1):
        hold_type: str = ""
        hold_market_value: Decimal = Decimal("0.0")
        if hold_type == 'STK':
            ws_stocks_value += hold_market_value
        elif hold_type == 'BND':
            ws_bonds_value += hold_market_value
        elif hold_type == 'CSH':
            ws_cash_value += hold_market_value
    ws_stocks_pct: Decimal = (ws_stocks_value / ws_total_value) * 100
    ws_bonds_pct: Decimal = (ws_bonds_value / ws_total_value) * 100
    ws_cash_pct: Decimal = (ws_cash_value / ws_total_value) * 100
    ws_rebalance_needed: str = ""
    ws_stocks_diff: Decimal = Decimal("0.0")
    ws_bonds_diff: Decimal = Decimal("0.0")
    return ws_rebalance_needed, ws_stocks_diff, ws_bonds_diff

def compare_to_target_C7(ws_target_stocks_pct: Decimal, ws_target_bonds_pct: Decimal, ws_stocks_diff: Decimal, ws_bonds_diff: Decimal) -> str:
    """Compares current allocation to target."""
    ws_rebalance_needed: str = 'N'
    if abs(ws_stocks_diff) > 5:
        ws_rebalance_needed = 'Y'
    if abs(ws_bonds_diff) > 5:
        ws_rebalance_needed = 'Y'
    return ws_rebalance_needed

def generate_rebalance_trades_C7(ws_total_value: Decimal, ws_stocks_diff: Decimal):
    """Generates rebalance trades."""
    if ws_stocks_diff > 0:
        ws_sell_amount: Decimal = ws_total_value * ws_stocks_diff / 100
        create_sell_order_C7(ws_sell_amount)
    else:
        ws_buy_amount: Decimal = ws_total_value * (0 - ws_stocks_diff) / 100
        create_buy_order_C7(ws_buy_amount)

def create_sell_order_C7(ws_sell_amount: Decimal):
    """Creates a sell order."""
    ws_trade_type: str = 'SELL'
    ws_order_type: str = 'MARKET'
    ws_trade_amount: Decimal = ws_sell_amount
    trade_execution_C7()

def create_buy_order_C7(ws_buy_amount: Decimal):
    """Creates a buy order."""
    ws_trade_type: str = 'BUY '
    ws_order_type: str = 'MARKET'
    ws_trade_amount: Decimal = ws_buy_amount
    trade_execution_C7()

