def process_authorization_C12() -> None:
    """Processes authorization."""
    global WS_CARD_VALID_C12
    validate_card_C12()
    if WS_CARD_VALID_C12 == 'Y':
        check_fraud_score_C12()
        global WS_FRAUD_APPROVED_C12
        if WS_FRAUD_APPROVED_C12 == 'Y':
            check_available_credit_C12()
            global WS_CREDIT_AVAILABLE_C12
            if WS_CREDIT_AVAILABLE_C12 == 'Y':
                approve_auth_C12()
            else:
                decline_auth_C12()
        else:
            decline_auth_C12()
    else:
        decline_auth_C12()

def validate_card_C12() -> None:
    """Validates a card."""
    global WS_CARD_VALID_C12
    WS_CARD_VALID_C12 = 'N'
    check_luhn_C12()
    global WS_LUHN_VALID_C12
    if WS_LUHN_VALID_C12 == 'Y':
        check_expiry_C12()
        global WS_NOT_EXPIRED_C12
        if WS_NOT_EXPIRED_C12 == 'Y':
            check_cvv_C12()
            global WS_CVV_VALID_C12
            if WS_CVV_VALID_C12 == 'Y':
                WS_CARD_VALID_C12 = 'Y'

def check_luhn_C12() -> None:
    """Checks Luhn algorithm."""
    global WS_LUHN_SUM_C12, WS_LUHN_IDX_C12, WS_LUHN_DIGIT_C12, WS_AUTH_CARD_NUMBER_C12, WS_LUHN_VALID_C12
    WS_LUHN_SUM_C12 = 0
    WS_LUHN_IDX_C12 = 16
    while True:
        if WS_LUHN_IDX_C12 < 1:
            break
        # WS_LUHN_DIGIT_C12 = WS_AUTH_CARD_NUMBER_C12(WS_LUHN_IDX_C12:1)
        if (17 - WS_LUHN_IDX_C12) % 2 == 0:
            WS_LUHN_DIGIT_C12 *= 2
            if WS_LUHN_DIGIT_C12 > 9:
                WS_LUHN_DIGIT_C12 -= 9
        WS_LUHN_SUM_C12 += None  # TODO: was WS_LUHN_DIGIT_C12
        WS_LUHN_IDX_C12 -= 1
    if WS_LUHN_SUM_C12 % 10 == 0:
        WS_LUHN_VALID_C12 = 'Y'
    else:
        WS_LUHN_VALID_C12 = 'N'

def check_expiry_C12() -> None:
    """Checks expiry date."""
