def invest_excess_reserves_C13() -> None:
    """Invest excess reserves."""
    ws_treasury_management: WsTreasuryManagementC13 = WsTreasuryManagementC13()
    ws_min_invest_amount: Decimal = Decimal("0.00")
    if ws_treasury_management.ws_excess_reserves > ws_min_invest_amount:
        sell_fed_funds_C13()

def sell_fed_funds_C13() -> None:
    """Sell fed funds."""
    ff_trans_type: str = ""
    ws_treasury_management: WsTreasuryManagementC13 = WsTreasuryManagementC13()
    ff_amount: Decimal = ws_treasury_management.ws_excess_reserves
