WS_IC_BALANCE: IntercompanyBalanceC15 = IntercompanyBalanceC15()

def load_ic_balances_C15() -> None:
    """Loads intercompany balances from file."""
    global WS_EOF_FLAG, WS_IC_COUNT, WS_IC_ARRAY
    WS_IC_COUNT = 0
    WS_EOF_FLAG = 'N'
    while WS_EOF_FLAG != 'Y':
        try:
            ws_ic_balance = read_intercompany_file()
            WS_IC_COUNT += 1
            if len(WS_IC_ARRAY) <= WS_IC_COUNT:
                WS_IC_ARRAY.append("")
            WS_IC_ARRAY[WS_IC_COUNT - 1] = ws_ic_balance
        except EOFError:
            WS_EOF_FLAG = 'Y'
    WS_EOF_FLAG = 'N'

