WS_SEARCH_TO: str = ""

def find_ic_counterpart_C15(ws_ic_idx: int) -> None:
    """Finds matching counterpart for intercompany balance."""
    global WS_SEARCH_FROM, WS_SEARCH_TO
    WS_SEARCH_FROM = WS_IC_ARRAY[ws_ic_idx - 1].ic_from_entity
    WS_SEARCH_TO = WS_IC_ARRAY[ws_ic_idx - 1].ic_to_entity
    ws_ic_idx2: int = 1
    while ws_ic_idx2 <= WS_IC_COUNT:
        if WS_IC_ARRAY[ws_ic_idx2 - 1].ic_from_entity == WS_SEARCH_TO:
            if WS_IC_ARRAY[ws_ic_idx2 - 1].ic_to_entity == WS_SEARCH_FROM:
                ws_ic_diff: Decimal = WS_IC_ARRAY[ws_ic_idx - 1].ic_amount + WS_IC_ARRAY[ws_ic_idx2 - 1].ic_amount
                if ws_ic_diff != Decimal('0'):
                    log_ic_diff_C15(ws_ic_diff)
                break
        ws_ic_idx2 += 1

